function initFaq(){document.querySelectorAll(".faq-item").forEach(function(item){var question=item.querySelector(".faq-q");question&&question.addEventListener("click",function(){var isOpen=item.classList.contains("open");document.querySelectorAll(".faq-item").forEach(function(i){i.classList.remove("open")}),isOpen||item.classList.add("open")})})}